  await api.search('film','Example','2025','tmdb');const u=new URL(requests[0].url);assert.equal(u.hostname,'api.themoviedb.org');assert.equal(u.searchParams.get('query'),'Example');assert.equal(u.searchParams.get('primary_release_year'),'2025');assert.equal(requests[0].headers.Authorization,'Bearer secret');
