const claim=value=>({rank:'normal',mainsnak:{snaktype:'value',datavalue:{value}}});
const wikiFilm=(id='Q123')=>({id,labels:{en:{value:'Example'},ru:{value:'Пример'}},descriptions:{en:{value:'A film'}},claims:{P31:[claim({id:'Q11424'})],P577:[claim({time:'+2025-01-01T00:00:00Z'})],P57:[claim({id:'Q456'})],P345:[claim('tt1234567')]}});
function wikiTransport(requests,entity=wikiFilm()) {return async request=>{requests.push(request);const u=new URL(request.url),params=u.searchParams;if(params.get('action')==='wbsearchentities')return {status:200,json:{search:[{id:entity.id},{id:'Q999'}]}};if(params.get('action')==='wbgetentities')return {status:200,json:{entities:{[entity.id]:entity,Q999:{id:'Q999',claims:{P31:[claim({id:'Q5'})]}},Q456:{id:'Q456',labels:{en:{value:'Director'},ru:{value:'Режиссёр'}}}}}};throw new Error('unexpected request');};}
test('keyless movie search filters unrelated entities and fetches Wikidata metadata',async()=>{const e=environment(),requests=[],api=new e.T.Api(()=>'',wikiTransport(requests),async()=>{});const result=await api.search('film','Пример','2025');assert.equal(result.items.length,1);assert.equal(result.items[0].source,'wikidata');assert.equal(requests.every(r=>new URL(r.url).hostname==='www.wikidata.org'&&!r.headers.Authorization),true);const rec=await api.details(result.items[0]);assert.equal(rec.fields.imdb_id,'tt1234567');assert.equal(rec.fields.director[0],'Режиссёр');assert.equal(rec.fields.cover,undefined);assert.equal(rec.fields.source_url,'https://www.wikidata.org/wiki/Q123');assert.equal((await api.search('film','Пример','2024')).items.length,0);});
test('automatic movie providers prioritize authenticated results, fallback warnings contain no keys',async()=>{const e=environment(),requests=[],wiki=wikiTransport(requests),api=new e.T.Api(k=>k==='tmdb'?'secret':'',async request=>{if(new URL(request.url).hostname==='api.themoviedb.org')return {status:200,json:{results:[{id:1,title:'TMDB film'}]}};return wiki(request);},async()=>{});const result=await api.search('film','Example');assert.deepEqual(Array.from(result.items,i=>i.source),['tmdb','wikidata']);api.transport=async request=>new URL(request.url).hostname==='api.themoviedb.org'?{status:401}:wiki(request);const fallback=await api.search('film','Different');assert.equal(fallback.items[0].source,'wikidata');assert.ok(fallback.warnings[0].startsWith('tmdb:'));assert.equal(JSON.stringify(fallback).includes('secret'),false);});
test('automatic books prefer Chitai, fall back to Open Library then keyed Google; manual selection is isolated',async()=>{
 const e=environment(),hosts=[];let available='chitai';
 const api=new e.T.Api(k=>k==='google'?'secret':'',async request=>{const host=new URL(request.url).hostname;hosts.push(host);
 if(host==='www.chitai-gorod.ru')return {status:200,text:available==='chitai'?'<a href="/product/psihologiya-vliyaniya-2898239" title="Психология влияния (Роберт Чалдини)">Психология влияния</a>':''};
 return {status:200,json:host==='www.googleapis.com'?{items:[{id:'google1',volumeInfo:{title:'Психология влияния'}}]}:{docs:available==='openlibrary'?[{title:'Психология влияния',cover_edition_key:'OL1M'}]:[]}};
 },async()=>{});
 let result=await api.search('book','Психология влияния');assert.equal(result.items[0].source,'chitai');assert.deepEqual(hosts,['www.chitai-gorod.ru']);
 available='openlibrary';hosts.length=0;result=await api.search('book','Психология влияния Чалдини');assert.equal(result.items[0].source,'openlibrary');assert.deepEqual(hosts,['www.chitai-gorod.ru','openlibrary.org']);
 available='google';hosts.length=0;result=await api.search('book','Психология влияния Роберт Чалдини');assert.equal(result.items[0].source,'google');assert.equal(hosts.at(-1),'www.googleapis.com');
 hosts.length=0;await api.search('book','Психология влияния','','google');assert.deepEqual(hosts,['www.googleapis.com']);
});
