test('merge refuses stale previews and concurrent edits after backup; undo refuses later edits',async()=>{const e=environment(),raw=fm({type:'film',title:'Manual'}),f=appFixture({'Shelf/Movie.md':raw}),p=new e.Plugin(f.app);await p.onload();const file=f.entries.get('Shelf/Movie.md');await assert.rejects(p.mergeMetadata(file,record(),'stale'),/Карточка была изменена/);assert.equal(f.writes.length,0);const original=f.app.vault.process;f.app.vault.process=async(file,callback)=>{f.content.set(file.path,raw+'Concurrent edit\n');return original(file,callback);};await assert.rejects(p.mergeMetadata(file,record(),raw),/Карточка была изменена/);assert.equal(f.content.get(file.path),raw+'Concurrent edit\n');assert.equal(p.lastMetadataChange,undefined);f.app.vault.process=original;await p.mergeMetadata(file,record(),f.content.get(file.path));f.content.set(file.path,f.content.get(file.path)+'Later edit\n');await assert.rejects(p.undoMetadata(),/Карточка была изменена/);assert.ok(f.content.get(file.path).endsWith('Later edit\n'));});
