function taskNotesFixture(f,options={}) {
 const tasks=new Map(),calls=[],active=[];let seq=0;
 const api={apiVersion:1,hasCapability:name=>!options.missing?.includes(name),tasks:{
  async list(){calls.push(['list']);return [...tasks.values()];},async get(path){return tasks.get(path)||null;},
  async create(data,context){calls.push(['create',data,context]);const path=`TaskNotes/Tasks/Created-${++seq}.md`;await f.app.vault.createFolder('TaskNotes').catch(()=>{});await f.app.vault.createFolder('TaskNotes/Tasks').catch(()=>{});await f.app.vault.create(path,fm({title:data.title,status:'custom-default',rating:4,scheduled:data.scheduled||null})+'\n'+data.details+'\n');const task={path,title:data.title,status:'custom-default'};tasks.set(path,task);return task;}
 },time:{async active(){return active;},async start(path,data,context){calls.push(['start',path,data,context]);active.push({taskPath:path});return tasks.get(path);},async stop(path){calls.push(['stop',path]);const index=active.findIndex(e=>e.taskPath===path);if(index>=0)active.splice(index,1);return tasks.get(path);}}};
 f.app.plugins={getPlugin:id=>id==='tasknotes'?{api}:null};
 const add=(path,title='Existing task',raw=fm({title,status:'work',priority:'my-priority',tags:['personal']})+'\n## Notes\nPrivate notes\n')=>{const file=f.file(path,raw);tasks.set(path,{path,title,status:'work'});return file;};return {api,tasks,calls,active,add};
}
