const sortRow=(title,values={})=>({file:{basename:title,path:title+'.md'},fm:{title,...values}});
const sortedNames=(T,rows,key,direction='desc')=>Array.from(T.sortItems([...rows],{key,direction},'ru'),i=>i.fm.title);
