test('invalid saved sorting falls back safely and a failed save keeps current sorting',async()=>{
 const e=environment(),f=appFixture(),p=new e.Plugin(f.app);p.data={sorting:{film:{key:'garbage',direction:'sideways'},book:{key:'title'}}};await p.onload();assert.equal(p.options.sorting.film.key,'current');assert.equal(p.options.sorting.film.direction,'desc');assert.equal(p.options.sorting.book.direction,'asc');p.saveData=async()=>{throw new Error('disk');};await assert.rejects(p.setSorting('film',{key:'year',direction:'asc'}),/disk/);assert.equal(p.options.sorting.film.key,'current');p.onunload();
});
